import unicodedata

def normalize_key(value):
    text = unicodedata.normalize(
        "NFKD",
        value or "",
    )

    text = "".join(
        character
        for character in text
        if not unicodedata.combining(character)
    )

    text = (
        text.lower()
        .replace("_", " ")
        .replace("-", " ")
    )

    return " ".join(text.split())


