def normalize_catalog_values(
    apps,
    schema_editor,
):
    CatalogItem = apps.get_model(
        "core",
        "CatalogItem",
    )

    unknown_values = set()
    updated = 0

    for item in CatalogItem.objects.all().iterator():
        category_match = VALUE_MAP.get(
            normalize_key(item.category)
        )

        subcategory_match = VALUE_MAP.get(
            normalize_key(item.subcategory)
        )

        new_category = None
        new_subcategory = ""

        if category_match:
            new_category, new_subcategory = (
                category_match
            )

        if (
            subcategory_match
            and subcategory_match[1]
        ):
            new_category, new_subcategory = (
                subcategory_match
            )

        if not new_category:
            unknown_values.add(
                (
                    item.category or "",
                    item.subcategory or "",
                )
            )
            continue

        changed_fields = []

        if item.category != new_category:
            item.category = new_category
            changed_fields.append("category")

        if (
            (item.subcategory or "")
            != new_subcategory
        ):
            item.subcategory = new_subcategory
            changed_fields.append("subcategory")

        if changed_fields:
            item.save(
                update_fields=changed_fields
            )
            updated += 1

    print(
        f"Productos normalizados: {updated}"
    )

    if unknown_values:
        print(
            "Valores no reconocidos:"
        )

        for category, subcategory in sorted(
            unknown_values
        ):
            print(
                repr(category),
                repr(subcategory),
            )

